solutionCode:
function App() {
  const users = [
    { id: 1, name: 'Ada', active: true },
    { id: 2, name: 'Linus', active: false },
    { id: 3, name: 'Grace', active: true },
    { id: 4, name: 'Dennis', active: true },
  ];
  return (
    <ul>
      {users.filter(u => u.active).map(u => <li key={u.id}>{u.name}</li>)}
    </ul>
  );
}
